from solution import is_simple_power
import threading
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


def call_with_timeout(func, args, timeout=0.5):
    """Run func(*args) in daemon thread, return (completed, result)."""
    box = {}
    def target():
        try:
            box["result"] = func(*args)
        except BaseException as e:
            box["error"] = e
    t = threading.Thread(target=target, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        return (False, None)
    if "error" in box:
        raise box["error"]
    return (True, box.get("result"))


# ---- explicit spec examples ----
@pytest.mark.parametrize(
    "x,n,expected",
    [
        (1, 4, True),
        (2, 2, True),
        (8, 2, True),
        (3, 2, False),
        (3, 1, False),
        (5, 3, False),
    ],
)
def test_spec_examples(x, n, expected):
    assert is_simple_power(x, n) is expected


# 1 == n**0 for any n, so 1 is a simple power of any n
@given(n=st.integers(min_value=-10, max_value=10))
def test_one_is_simple_power_of_any_n(n):
    assert is_simple_power(1, n) is True


# n==1: only 1 is a power (1**k == 1)
@given(x=st.integers(min_value=-5, max_value=20))
def test_base_one_only_one_is_power(x):
    expected = (x == 1)
    assert is_simple_power(x, 1) is expected


# Exact powers must be recognised: if x == n**k for some k>=0 then True.
# Covers negative bases with odd exponent and 0**k == 0.
@given(
    n=st.integers(min_value=-5, max_value=5),
    k=st.integers(min_value=0, max_value=6),
)
def test_exact_nonnegative_powers_are_true(n, k):
    x = n ** k  # Python semantics, n**0 == 1 including 0**0
    # 0**0 == 1 case is x==1 which is covered; skip ambiguous 0-base
    # generation that hangs is avoided because x == n**k terminates;
    # but filter the hanging-prone (n==0 and x not in (0,1)) -- cannot happen here
    # since x is exactly 0 or 1 when n==0.
    assert is_simple_power(x, n) is True


def test_zero_is_power_of_zero():
    # 0**1 == 0 so exists int with 0**int == 0
    assert is_simple_power(0, 0) is True


def test_zero_is_power_of_zero_base():
    # 0**2 == 0
    assert is_simple_power(0, 5) is False  # sanity: 5**k never 0
    assert is_simple_power(0, 0) is True


@pytest.mark.parametrize(
    "x,n",
    [
        (-8, -2),   # (-2)**3 == -8
        (-27, -3),  # (-3)**3 == -27
        (-32, -2),  # (-2)**5 == -32
        (-1, -1),   # (-1)**1 == -1
        (-1, -5),
    ],
)
def test_negative_odd_powers_are_true(x, n):
    assert is_simple_power(x, n) is True


@pytest.mark.parametrize(
    "x,n",
    [
        (4, -2),   # (-2)**2 == 4
        (9, -3),   # (-3)**2 == 9
        (1, -7),
    ],
)
def test_negative_base_even_powers_are_true(x, n):
    assert is_simple_power(x, n) is True


# Non-powers for positive bases: brute-force reference over k>=0
@given(
    x=st.integers(min_value=0, max_value=50),
    n=st.integers(min_value=2, max_value=5),
)
def test_non_powers_positive_base(x, n):
    # reference: exists k>=0 with n**k == x ?
    # (for |n|>=2 and integer x, negative k gives fractions, never integer x
    #  except x==0 which is never a power, so k>=0 suffices)
    expected = any(n ** k == x for k in range(0, 20))
    assert is_simple_power(x, n) is expected


@given(
    x=st.integers(min_value=-50, max_value=-1),
    n=st.integers(min_value=2, max_value=5),
)
def test_negative_x_positive_n_is_false(x, n):
    # n>=2, n**k > 0 for all k>=0, negative k gives positive fraction;
    # never equals negative integer x
    assert is_simple_power(x, n) is False


def test_termination_zero_base_non_power():
    # No k with 0**k == 2 (0**0==1, 0**k==0 for k>0), so must return False
    # instead of looping forever.
    completed, result = call_with_timeout(is_simple_power, (2, 0), timeout=0.5)
    assert completed, "is_simple_power(2, 0) did not terminate"
    assert result is False


def test_termination_zero_base_larger():
    # 0**k is only 1 or 0, never 5
    completed, result = call_with_timeout(is_simple_power, (5, 0), timeout=0.5)
    assert completed, "is_simple_power(5, 0) did not terminate"
    assert result is False


def test_termination_minus_one_base():
    # (-1)**k is only 1 or -1, never 2, must return False quickly
    completed, result = call_with_timeout(is_simple_power, (2, -1), timeout=0.5)
    assert completed, "is_simple_power(2, -1) did not terminate"
    assert result is False


def test_termination_minus_one_base_three():
    completed, result = call_with_timeout(is_simple_power, (3, -1), timeout=0.5)
    assert completed, "is_simple_power(3, -1) did not terminate"
    assert result is False
